  "steps": [
    {
      "id": 1,
      "claim": "CT scans are expensive medical procedures.",
      "evidence": "Typical U.S. charges range from $300 to $3,000 before insurance adjustments (Health Care Cost Institute data).",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Uninsured individuals must pay the full price out‑of‑pocket.",
      "evidence": "By definition, uninsured patients have no third‑party payer; billing statements show they receive the undiscounted charge.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Insured individuals usually have most of the CT cost covered by their health plan.",
      "evidence": "Private and public plans include diagnostic imaging benefits; patients typically pay only a copay or deductible far lower than the full charge (CMS reports).",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 4,
      "claim": "Higher out‑of‑pocket costs are a strong determinant of whether patients accept recommended imaging.",
      "evidence": "Health‑services research (e.g., Miller et al., 2012; National Hospital Ambulatory Medical Care Survey) shows uninsured patients have significantly lower CT utilization than insured patients after adjusting for clinical need, indicating cost sensitivity.",
      "weight": 0.30,
      "depends_on": [1, 2, 3]
    },
    {
      "id": 5,
      "claim": "Therefore, an uninsured person is more likely than an insured person to decline a CT scan.",
      "evidence": "Because uninsured patients face the full price while insured patients face only a reduced copay, the financial barrier is greater, leading to the higher refusal rates documented in empirical studies.",
      "weight": 0.25,
      "depends_on": [4]
    }
  ],
  "considered": [
    {
      "answer": "No",
      "reason_rejected": "Empirical evidence consistently shows lower CT utilization among uninsured patients, and cost is a primary driver of that difference; there is no credible data indicating uninsured individuals are more likely to accept the scan."
    }
  ]
